CREATE TABLE IF NOT EXISTS "project" ( "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" text NOT NULL, "status" varchar NOT NULL );
CREATE TABLE IF NOT EXISTS "project_platform" ( "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "project_id" integer NOT NULL UNIQUE, "platform_id" varchar NOT NULL, FOREIGN KEY ("project_id") REFERENCES "project" ("id") );
CREATE TABLE IF NOT EXISTS "category" ( "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(32) NOT NULL UNIQUE );
CREATE TABLE IF NOT EXISTS "project_category" ( "project_id" integer NOT NULL, "category_id" integer NOT NULL, CONSTRAINT "pk-project_category" PRIMARY KEY ("project_id", "category_id"), FOREIGN KEY ("project_id") REFERENCES "project" ("id"), FOREIGN KEY ("category_id") REFERENCES "category" ("id") );
CREATE TABLE IF NOT EXISTS "semantic_node" ( "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" text NOT NULL, "definition" text NOT NULL, "description" text NOT NULL, "category" varchar(32) NOT NULL );
CREATE TABLE IF NOT EXISTS "semantic_function" ( "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "semantic_node_id" integer NOT NULL, "function_name" varchar NOT NULL, "contract_path" varchar NOT NULL, FOREIGN KEY ("semantic_node_id") REFERENCES "semantic_node" ("id") );
CREATE TABLE IF NOT EXISTS "semantic_merge" ( "from_semantic_id" integer NOT NULL, "to_semantic_id" integer NOT NULL, "appended_description" text NOT NULL, CONSTRAINT "pk-semantic_merge" PRIMARY KEY ("from_semantic_id", "to_semantic_id"), FOREIGN KEY ("from_semantic_id") REFERENCES "semantic_node" ("id") ON DELETE CASCADE ON UPDATE CASCADE, FOREIGN KEY ("to_semantic_id") REFERENCES "semantic_node" ("id") ON DELETE RESTRICT ON UPDATE CASCADE );
CREATE TABLE IF NOT EXISTS "audit_finding" ( "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" text NOT NULL, "severity" varchar(16) NOT NULL, "root_cause" text NOT NULL, "description" text NOT NULL, "patterns" text NOT NULL, "exploits" text NOT NULL );
CREATE TABLE IF NOT EXISTS "finding_category" ( "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "category" varchar(32) NOT NULL, "name" varchar NOT NULL, "description" text NOT NULL );
CREATE TABLE IF NOT EXISTS "audit_finding_category" ( "audit_finding_id" integer NOT NULL, "finding_category_id" integer NOT NULL, CONSTRAINT "pk-audit_finding_category" PRIMARY KEY ("audit_finding_id", "finding_category_id"), FOREIGN KEY ("audit_finding_id") REFERENCES "audit_finding" ("id"), FOREIGN KEY ("finding_category_id") REFERENCES "finding_category" ("id") );
CREATE TABLE IF NOT EXISTS "semantic_finding_link" ( "semantic_node_id" integer NOT NULL, "audit_finding_id" integer NOT NULL, "strength" varchar(16) NOT NULL, "evidence" text NOT NULL, CONSTRAINT "pk-semantic_finding_link" PRIMARY KEY ("semantic_node_id", "audit_finding_id"), FOREIGN KEY ("semantic_node_id") REFERENCES "semantic_node" ("id"), FOREIGN KEY ("audit_finding_id") REFERENCES "audit_finding" ("id") );
CREATE TABLE IF NOT EXISTS "finding_link_status" ( "audit_finding_id" integer NOT NULL PRIMARY KEY, FOREIGN KEY ("audit_finding_id") REFERENCES "audit_finding" ("id") );
CREATE TABLE IF NOT EXISTS "finding_merge" ( "from_finding_id" integer NOT NULL, "to_finding_id" integer NOT NULL, "appended_description" text NOT NULL, "appended_patterns" text NOT NULL, "appended_exploits" text NOT NULL, CONSTRAINT "pk-finding_merge" PRIMARY KEY ("from_finding_id", "to_finding_id"), FOREIGN KEY ("from_finding_id") REFERENCES "audit_finding" ("id") ON DELETE CASCADE ON UPDATE CASCADE, FOREIGN KEY ("to_finding_id") REFERENCES "audit_finding" ("id") ON DELETE RESTRICT ON UPDATE CASCADE );
CREATE TABLE IF NOT EXISTS "project_semantic" ( "project_id" integer NOT NULL, "semantic_node_id" integer NOT NULL, CONSTRAINT "pk-project_semantic" PRIMARY KEY ("project_id", "semantic_node_id"), FOREIGN KEY ("project_id") REFERENCES "project" ("id"), FOREIGN KEY ("semantic_node_id") REFERENCES "semantic_node" ("id") );
CREATE TABLE IF NOT EXISTS "project_finding" ( "project_id" integer NOT NULL, "audit_finding_id" integer NOT NULL, CONSTRAINT "pk-project_finding" PRIMARY KEY ("project_id", "audit_finding_id"), FOREIGN KEY ("project_id") REFERENCES "project" ("id"), FOREIGN KEY ("audit_finding_id") REFERENCES "audit_finding" ("id") );
CREATE TABLE IF NOT EXISTS "pending_semantic" ( "semantic_node_id" integer NOT NULL PRIMARY KEY, FOREIGN KEY ("semantic_node_id") REFERENCES "semantic_node" ("id") );
CREATE TABLE IF NOT EXISTS "merge_status" ( "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "source_key" varchar NOT NULL, "native_sem_ceiling" integer, "phase" varchar(16) NOT NULL );
CREATE TABLE IF NOT EXISTS "operation_history" ( "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "datetime" timestamp_with_timezone_text NOT NULL, "type" varchar(32) NOT NULL, "args" json_text NOT NULL );
